function _toolResultImageSrc(content) {
    const data = content.match(/['"]?data['"]?\s*[:=]\s*['"]([A-Za-z0-9+/=\s]{100,})['"]/);
    if (!data) return '';
    const media = content.match(/['"]?media_type['"]?\s*[:=]\s*['"]([^'"]+)['"]/);
    return `data:${media?.[1] || 'image/png'};base64,${data[1].replace(/\s/g, '')}`;
