function _loadImageSrc(img, src) {
    if (!src) return Promise.resolve(false);
    return new Promise(resolve => {
        const done = ok => {
            img.onload = null;
            img.onerror = null;
            resolve(ok);
        };
        img.onload = () => done(true);
        img.onerror = () => done(false);
        img.src = src;
    });
}

